const DEFINITION = /^\[(.+?)\]:\s+(\S.*)$/u

/**
 * Normalize a label the way every definition and every reference is compared: trimmed, with runs
 * of whitespace collapsed to one space, and lowercased.
 * @param {string} label - the label as written.
 * @returns {string} the normalized label.
 */
export function normalizeLabel(label) {
  return label.trim().replace(/\s+/gu, ' ').toLowerCase()
}

