 * @param {string} trimmed - the line's trimmed text.
 * @returns {{label: string, url: string}|undefined} the normalized label and the url, or undefined
 *   when the line is not a definition.
 */
export function parseDefinitionLine(trimmed) {
  const match = DEFINITION.exec(trimmed)
  if (match === null) return undefined
  return { label: normalizeLabel(match[1]), url: match[2] }
}
"}

