{"file_path":"src/defs.js","content":"/** A definitions file: one `[label]: url` per line, read before the document. */

import { readFileSync } from 'node:fs'
import { normalizeLabel, parseDefinitionLine } from './labels.js'

/** One refusal reading a definitions file, carrying the fully worded message. */
export class DefsError extends Error {
  constructor(message) {
    super(message)
    this.name = 'DefsError'
  }
}

/**
 * Read a definitions file into a map of normalized label to its url and source.
 * @param {string} path - the path named on the command line.
 * @returns {Map<string, {url: string, source: 'file'}>} the file's definitions.
 * @throws {DefsError} when the file cannot be read, has a line that is not a definition, or
 *   defines one label twice.
 */
export function loadDefinitionsFile(path) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    throw new DefsError(`cannot read definitions ${path}`)
  }
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const definitions = new Map()
  lines.forEach((raw, index) => {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return
    const definition = parseDefinitionLine(trimmed)
    if (definition === undefined) throw new DefsError(`${path}: line ${line}: expected [label]: <url>`)
    if (definitions.has(definition.label)) {
      throw new DefsError(`${path}: line ${line}: label ${normalizeLabel(definition.label)} is defined twice`)
    }
    definitions.set(definition.label, { url: definition.url, source: 'file' })
  })
  return definitions
}
"}

