import { escapeText } from './html.js'
import { renderInline } from './inline.js'
import { parseDefinitionLine } from './labels.js'

const FENCE = /^(`{3,})([^`]*)$/
const HEADING = /^(#{1,6}) (.*)$/
const ITEM = /^( *)- (.*)$/

/** One refusal of a document line, carrying the 1-based line it was read at. */
export class BlockError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'BlockError'
    this.line = line
  }
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * The blocks of one document, and the link definitions in force once it has been read.
 * @param {string[]} lines - the document's lines.
 * @param {Map<string, {url: string, source: string}>} [initialDefinitions] - definitions already
 *   in force before the document, keyed by normalized label.
 * @returns {{blocks: object[], definitions: Map<string, {url: string, source: string}>}} the
 *   blocks in document order, and every definition in force once the document has been read.
 * @throws {BlockError} on an unterminated fence or a label the document defines twice.
 */
export function parse(lines, initialDefinitions = new Map()) {
  const out = []
  const definitions = new Map(initialDefinitions)
  let paragraph = []
  let items
  let depthStack
  const flush = () => {
    if (paragraph.length > 0) {
      out.push({ kind: 'paragraph', lines: paragraph })
      paragraph = []
    }
    if (items !== undefined) {
      out.push({ kind: 'list', items })
      items = undefined
      depthStack = undefined
    }
  }
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index]
    const line = index + 1
    const fence = FENCE.exec(raw)
    if (fence !== null) {
      flush()
      const content = []
      let close = -1
      for (let scan = index + 1; scan < lines.length; scan += 1) {
        const candidate = lines[scan].trim()
        if (/^`{3,}$/u.test(candidate) && candidate.length >= fence[1].length) {
          close = scan
          break
        }
        content.push(lines[scan])
      }
      if (close === -1) throw new BlockError(line, 'unterminated code fence')
      out.push({ kind: 'fence', info: fence[2].trim().split(/\s+/u)[0], content })
      index = close
      continue
    }
    if (raw.trim() === '') {
      flush()
      continue
    }
    const definition = parseDefinitionLine(raw.trim())
    if (definition !== undefined) {
      flush()
      if (definitions.has(definition.label)) throw new BlockError(line, `label ${definition.label} is defined twice`)
      definitions.set(definition.label, { url: definition.url, source: 'document' })
      continue
    }
    const heading = HEADING.exec(raw)
    if (heading !== null) {
      flush()
      out.push({ kind: 'heading', level: heading[1].length, text: heading[2].trim() })
      continue
    }
    const item = ITEM.exec(raw)
    if (item !== null && paragraph.length === 0) {
      if (items === undefined) {
        items = []
        depthStack = []
      }
      const level = Math.min(Math.floor(item[1].length / 2), depthStack.length)
      const node = { text: item[2].trim() }
      if (level === 0) {
        items.push(node)
      } else {
        const parent = depthStack[level - 1]
        parent.children = parent.children ?? []
        parent.children.push(node)
      }
      depthStack[level] = node
      continue
    }
    if (items !== undefined) flush()
    paragraph.push(raw.trim())
  }
  flush()
  return { blocks: out, definitions }
}

/** Render one nested list to lines of HTML, `<ul>` and `</ul>` each on their own line. */
function renderList(items, definitions) {
  const lines = ['<ul>']
  for (const item of items) {
    if (item.children !== undefined && item.children.length > 0) {
      lines.push(`<li>${renderInline(item.text, definitions)}`, ...renderList(item.children, definitions), '</li>')
    } else {
      lines.push(`<li>${renderInline(item.text, definitions)}</li>`)
    }
  }
  lines.push('</ul>')
  return lines
}

/**
 * Render parsed blocks to HTML.
 * @param {readonly object[]} blocks - the document's blocks.
 * @param {Map<string, {url: string, source: string}>} [definitions] - the definitions in force,
 *   for resolving reference links.
 * @returns {string} the HTML, with a trailing newline unless the document holds no block.
 */
export function render(blocks, definitions = new Map()) {
  const rendered = blocks.map((block) => {
    if (block.kind === 'heading') return `<h${block.level}>${renderInline(block.text, definitions)}</h${block.level}>`
    if (block.kind === 'paragraph') {
      return `<p>${block.lines.map(text => renderInline(text, definitions)).join('\n')}</p>`
    }
    if (block.kind === 'list') return renderList(block.items, definitions).join('\n')
    const info = escapeText(block.info)
    const open = block.info === '' ? '<pre><code>' : `<pre><code class="language-${info}">`
    return `${open}${block.content.map(text => `${escapeText(text)}\n`).join('')}</code></pre>`
  })
  return rendered.length === 0 ? '' : `${rendered.join('\n')}\n`
}

/**
 * The headings of parsed blocks, for the outline.
 * @param {readonly object[]} blocks - the document's blocks.
 * @returns {{level: number, text: string}[]} the headings in document order.
 */
export function headings(blocks) {
  return blocks.filter(block => block.kind === 'heading').map(block => ({ level: block.level, text: block.text }))
}
"}

